// ===== L4185-L4196 renderAccountsMini =====
function renderAccountsMini() {
  if (!state.accounts.length) return `<div class="empty">暂无账号</div>`;
  return `
    <div class="table-wrap">
      <table>
        <thead><tr><th>账号</th><th>平台</th><th>定位</th></tr></thead>
        <tbody>${state.accounts.map((item) => `<tr><td>${item.accountName}</td><td>${item.platform}</td><td>${item.positioning || ""}</td></tr>`).join("")}</tbody>
      </table>
    </div>
  `;
}

function mountAccountsPagination() {
  setupPagination("accountsPagination", {
    pageSize: 20,
    fetchPage: async (page, pageSize, offset) => {
      const result = await api(`/api/accounts?limit=${pageSize}&offset=${offset}`);
      return result;
    },
    renderItems: (items) => {
      const tbody = document.getElementById("accountsTableBody");
      const countTag = document.getElementById("accountsCountTag");
      if (!tbody) return;
      if (!items.length) {
        tbody.innerHTML = `<tr><td colspan="8"><div class="empty">当前筛选条件下没有账号。</div></td></tr>`;
        if (countTag) countTag.textContent = "0 个账号";
        return;
      }
      tbody.innerHTML = items.map((item) => `
        <tr>
          <td><div class="cell-stack"><strong>${item.accountName}</strong><span class="muted">${item.profileUrl ? "已配置主页链接" : "未配置主页链接"}</span></div></td>
          <td>${item.employeeName || "-"}</td>
          <td><span class="tag ${item.platform === "抖音" ? "tag-warm" : ""}">${item.platform}</span></td>
          <td>${item.accountUid || "-"}</td>
          <td>${item.persona || "-"}</td>
          <td>${item.positioning || "-"}</td>
          <td><span class="tag ${item.status === "正常" ? "" : "tag-soft"}">${item.status}</span></td>
          <td><div class="actions"><button class="ghost js-edit-account" data-id="${item.id}">编辑</button><button class="ghost danger js-delete-account" data-id="${item.id}">删除</button></div></td>
        </tr>
      `).join("");
      if (countTag) countTag.textContent = `${items.length} 个账号`;
    }
  });
}


// ===== L5399-L5429 submitAccount / submitStaffPostingPlan =====
async function submitAccount(event) {
  event.preventDefault();
  const formData = new FormData(event.currentTarget);
  const payload = Object.fromEntries(formData.entries());
  const id = String(payload.id || "");
  delete payload.id;
  await api(id ? `/api/accounts/${id}` : "/api/accounts", {
    method: id ? "PUT" : "POST",
    body: JSON.stringify(payload)
  });
  state.editingAccountId = "";
  setFlash("success", id ? "账号信息已更新" : "账号已创建", "账号已经进入主管端管理范围，员工录作品时就能选择它。");
  await loadData();
  renderApp();
}

async function submitStaffPostingPlan(event) {
  event.preventDefault();
  const formData = new FormData(event.currentTarget);
  const id = String(formData.get("id") || "");
  await api(`/api/accounts/${id}/posting-plan`, {
    method: "PUT",
    body: JSON.stringify({
      postingPlan: String(formData.get("postingPlan") || "")
    })
  });
  setFlash("success", "账号规划已保存", "主管端作品看板现在可以同步查看这条账号规划。");
  await loadData();
  renderApp();
}


// ===== L5438-L5445 deleteAccount =====
async function deleteAccount(id) {
  if (!window.confirm("确认删除该账号及其关联作品/客资吗？")) return;
  await api(`/api/accounts/${id}`, { method: "DELETE" });
  state.editingAccountId = state.editingAccountId === id ? "" : state.editingAccountId;
  await loadData();
  renderApp();
}


// ===== L5462-L5473 submitStaffUser =====
async function submitStaffUser(event) {
  event.preventDefault();
  const formData = new FormData(event.currentTarget);
  await api("/api/users/staff", {
    method: "POST",
    body: JSON.stringify(Object.fromEntries(formData.entries()))
  });
  setFlash("success", "员工登录账号已创建", "把用户名和密码发给对应员工，他就可以开始录作品和客资。");
  await loadData();
  renderApp();
}

